CREATE INDEX IF NOT EXISTS idx_original_tokens_verse_order ON original_tokens(verse_id, word_order);
CREATE OR REPLACE VIEW v_interlinear_tokens AS SELECT ot.id, ot.verse_id, ot.word_order, ot.language, ot.surface_text, ot.strong_number, left(ot.strong_number,5) AS base_strong, ot.lemma, ot.morph, ot.source_verse_id, sl.original_word AS lex_word, sl.transliteration, sl.gloss, sl.definition_html FROM original_tokens ot LEFT JOIN LATERAL (SELECT original_word, transliteration, gloss, definition_html FROM strongs_lexicon s WHERE s.extended_strong=ot.strong_number OR s.base_strong=left(ot.strong_number,5) ORDER BY (s.extended_strong=ot.strong_number) DESC, s.extended_strong ASC LIMIT 1) sl ON true;
CREATE OR REPLACE VIEW v_daily_reading_verses AS SELECT dp.day, dp.section, dp.id AS passage_id, v.id AS verse_id, v.book_code, v.chapter, v.verse, v.verse_order FROM daily_passages dp JOIN verses v1 ON v1.id=dp.start_verse_id JOIN verses v2 ON v2.id=dp.end_verse_id JOIN verses v ON v.verse_order BETWEEN v1.verse_order AND v2.verse_order WHERE EXISTS (SELECT 1 FROM verse_alignments va WHERE va.english_verse_id=v.id);
